import type { Metadata } from "next";
import { setRequestLocale } from "next-intl/server";
import { redirect } from "@/i18n/navigation";
import { decodeAnswers } from "@/lib/answers";
import { ResultsView } from "@/components/results/ResultsView";
import { SiteHeader } from "@/components/SiteHeader";
import { SiteFooter } from "@/components/SiteFooter";

// Results are per-visitor and generated by the model: thin, near-duplicate
// pages that would dilute the catalog in the index. Crawling stays allowed so
// social crawlers can read the OG tags on a shared link.
export const metadata: Metadata = {
  robots: { index: false, follow: true },
};

export default async function ResultsPage({
  params,
  searchParams,
}: PageProps<"/[locale]/results">) {
  const { locale } = await params;
  setRequestLocale(locale);

  const decoded = decodeAnswers(await searchParams);
  if (!decoded) {
    redirect({ href: "/quiz", locale });
  }

  return (
    <main className="flex flex-1 flex-col">
      <SiteHeader />
      <ResultsView answers={decoded!.answers} mode={decoded!.mode} />
      <SiteFooter />
    </main>
  );
}
